import React from 'react';

const RewardCard = ({ dayStreak, rewardAmount, onClaim }) => {
  return (
    <div className="card text-center">
      <div className="card-header">
        <h3>Day {dayStreak} Reward</h3>
      </div>
      <div className="card-body">
        <h2 className="text-success">{rewardAmount.toLocaleString()} €</h2>
        <p className="card-text">Log in daily to claim your reward!</p>
        <button className="btn btn-primary w-100" onClick={onClaim}>
          Claim Reward
        </button>
      </div>
    </div>
  );
};

export default RewardCard;
